-- Baseline: the schema that EnsureCreated produced before versioned migrations existed.
-- Every statement is idempotent so an existing database (Neon production) is adopted as-is.

CREATE TABLE IF NOT EXISTS "Sims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Operator" text NOT NULL,
    "PhoneNumber" text NOT NULL,
    "Iccid" text NOT NULL,
    "PlanType" text NOT NULL,
    "MonthlyCost" numeric(12,2) NOT NULL,
    "ContractStart" date NULL,
    "ContractEnd" date NULL,
    "Status" varchar(30) NOT NULL,
    "CostCentre" text NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Sims_Iccid" ON "Sims" ("Iccid");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Sims_PhoneNumber" ON "Sims" ("PhoneNumber");

CREATE TABLE IF NOT EXISTS "Users" (
    "Id" uuid PRIMARY KEY,
    "Email" varchar(320) NOT NULL,
    "DisplayName" varchar(160) NOT NULL,
    "Role" varchar(40) NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedAt" timestamptz NOT NULL,
    "UpdatedAt" timestamptz NOT NULL,
    "DisabledAt" timestamptz NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Users_Email" ON "Users" ("Email");

CREATE TABLE IF NOT EXISTS "Employees" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "EmployeeNumber" varchar(80) NOT NULL,
    "FullName" varchar(200) NOT NULL,
    "Email" varchar(320) NULL,
    "Department" varchar(120) NOT NULL,
    "CostCentre" varchar(80) NOT NULL,
    "Status" varchar(30) NOT NULL,
    "CreatedAt" timestamptz NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Employees_EmployeeNumber" ON "Employees" ("EmployeeNumber");

CREATE TABLE IF NOT EXISTS "Assignments" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SimId" integer NOT NULL REFERENCES "Sims" ("Id") ON DELETE RESTRICT,
    "EmployeeId" integer NOT NULL REFERENCES "Employees" ("Id") ON DELETE RESTRICT,
    "AssignedByUserId" uuid NOT NULL,
    "AssignedAt" timestamptz NOT NULL,
    "ReturnedAt" timestamptz NULL,
    "ReturnedByUserId" uuid NULL,
    "Notes" varchar(1000) NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Assignments_SimId" ON "Assignments" ("SimId") WHERE "ReturnedAt" IS NULL;
CREATE INDEX IF NOT EXISTS "IX_Assignments_EmployeeId" ON "Assignments" ("EmployeeId");

CREATE TABLE IF NOT EXISTS "AuditEvents" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ActorUserId" uuid NULL,
    "ActorEmail" varchar(320) NOT NULL,
    "Action" varchar(100) NOT NULL,
    "EntityType" varchar(100) NOT NULL,
    "EntityId" varchar(200) NOT NULL,
    "Details" text NOT NULL,
    "CreatedAt" timestamptz NOT NULL,
    "PreviousHash" varchar(64) NOT NULL,
    "Hash" varchar(64) NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_AuditEvents_CreatedAt" ON "AuditEvents" ("CreatedAt");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_AuditEvents_Hash" ON "AuditEvents" ("Hash");
